// ========================================
// My Games - Interactive Library Manager
// ========================================

// DOM Elements
const collectionList = document.querySelector('.collection-list');
const searchInput = document.querySelector('.search-input');
const sortButtons = document.querySelectorAll('.sort-btn');
const statusCheckboxes = document.querySelectorAll('.checkbox-item input[type="checkbox"]');
const applyButton = document.querySelector('.apply-btn');

// State
let currentSort = 'asc'; // 'asc' or 'desc'
let searchTerm = '';
// Modal state
let gameToDelete = null;

let activeFilters = {
  planning: true,
  progress: true,
  finished: true,
  dropped: false
};

// ========================================
// Status Dropdown Management
// ========================================

const statusOptions = [
  { value: 'planning', label: 'Planning', class: 'status-planning' },
  { value: 'progress', label: 'On Progress', class: 'status-progress' },
  { value: 'finished', label: 'Finished', class: 'status-finished' },
  { value: 'dropped', label: 'Dropped', class: 'status-dropped' }
];

function createStatusDropdown() {
  const dropdown = document.createElement('div');
  dropdown.className = 'status-dropdown';
  dropdown.innerHTML = statusOptions.map(option => `
    <button class="status-option ${option.class}" data-status="${option.value}">
      ${option.label}
    </button>
  `).join('');
  return dropdown;
}

function toggleStatusDropdown(button) {
  const existingDropdown = document.querySelector('.status-dropdown');
  const parentCard = button.closest('.game-card');
  
  // Close existing dropdown if clicking same button or another button
  if (existingDropdown) {
    const prevCard = existingDropdown.closest('.game-card');
    if (prevCard) prevCard.classList.remove('dropdown-open');
    const isSameButton = existingDropdown.parentElement === button;
    existingDropdown.remove();
    if (isSameButton) return;
  }
  
  // Create and position new dropdown (always downwards)
  const dropdown = createStatusDropdown();
  if (parentCard) parentCard.classList.add('dropdown-open');
  button.appendChild(dropdown);
  
  // Add click handlers to dropdown options
  dropdown.querySelectorAll('.status-option').forEach(option => {
    option.addEventListener('click', (e) => {
      e.stopPropagation();
      const newStatus = option.dataset.status;
      updateGameStatus(button, newStatus);
      if (parentCard) parentCard.classList.remove('dropdown-open');
      dropdown.remove();
    });
  });
  
  // Position dropdown
  setTimeout(() => {
    dropdown.style.opacity = '1';
    dropdown.style.transform = 'translateY(0)';
  }, 10);
}

function updateGameStatus(button, newStatus) {
  const statusText = button.querySelector('.status-text');
  const selectedOption = statusOptions.find(opt => opt.value === newStatus);
  
  // Update text and class
  statusText.textContent = selectedOption.label;
  statusText.className = 'status-text ' + selectedOption.class;
}

// ========================================
// Search Functionality
// ========================================

function handleSearch(query) {
  searchTerm = query.toLowerCase().trim();
  applyFiltersAndSort();
}

// ========================================
// Sort Functionality
// ========================================

function handleSort(direction) {
  currentSort = direction;
  
  // Update button states
  sortButtons.forEach(btn => {
    const isAsc = btn.querySelector('span').textContent.includes('0');
    if ((direction === 'asc' && isAsc) || (direction === 'desc' && !isAsc)) {
      btn.classList.add('active');
    } else {
      btn.classList.remove('active');
    }
  });
  
  applyFiltersAndSort();
}

// ========================================
// Filter & Sort Application
// ========================================

function applyFiltersAndSort() {
  const gameCards = Array.from(collectionList.querySelectorAll('.game-card'));
  
  gameCards.forEach(card => {
    const title = card.querySelector('.card-title').textContent.toLowerCase();
    const statusText = card.querySelector('.status-text').textContent.toLowerCase();
    
    // Determine status type
    let statusType = 'planning';
    if (statusText.includes('progress')) statusType = 'progress';
    else if (statusText.includes('finished')) statusType = 'finished';
    else if (statusText.includes('dropped')) statusType = 'dropped';
    
    // Check if should be visible
    const matchesSearch = !searchTerm || title.includes(searchTerm);
    const matchesFilter = activeFilters[statusType];
    
    // Show or hide card
    if (matchesSearch && matchesFilter) {
      card.style.display = '';
      card.style.animation = 'fadeIn 0.3s ease';
    } else {
      card.style.display = 'none';
    }
  });
  
  // Sort visible cards
  const visibleCards = gameCards.filter(card => card.style.display !== 'none');
  visibleCards.sort((a, b) => {
    const titleA = a.querySelector('.card-title').textContent;
    const titleB = b.querySelector('.card-title').textContent;
    
    if (currentSort === 'asc') {
      return titleA.localeCompare(titleB);
    } else {
      return titleB.localeCompare(titleA);
    }
  });
  
  // Reorder in DOM
  visibleCards.forEach(card => collectionList.appendChild(card));
  
}

// ========================================
// Filter Management
// ========================================

function updateFilterState() {
  statusCheckboxes.forEach(checkbox => {
    const label = checkbox.nextElementSibling;
    const statusName = label.textContent.toLowerCase().trim();
    
    let filterKey = 'planning';
    if (statusName.includes('progress')) filterKey = 'progress';
    else if (statusName === 'finished') filterKey = 'finished';
    else if (statusName === 'dropped') filterKey = 'dropped';
    
    activeFilters[filterKey] = checkbox.checked;
    
    // Update visual checkbox state
    const checkboxSpan = checkbox.previousElementSibling;
    if (checkbox.checked) {
      checkboxSpan.classList.add('checked');
    } else {
      checkboxSpan.classList.remove('checked');
    }
  });
}

// ========================================
// Delete Functionality
// ========================================

function openDeleteModal(button) {
  const gameCard = button.closest('.game-card');
  const gameTitle = gameCard.querySelector('.card-title').textContent;
  
  // Store reference to the game card being deleted
  gameToDelete = gameCard;
  
  // Show modal
  const modal = document.getElementById('deleteModal');
  modal.classList.add('show');
}

function confirmDeleteGame() {
  if (!gameToDelete) return;
  
  // Fade out animation
  gameToDelete.style.animation = 'fadeOut 0.3s ease';
  
  setTimeout(() => {
    gameToDelete.remove();
    gameToDelete = null;
    refreshPagination();
    closeDeleteModal();
  }, 300);
}

function closeDeleteModal() {
  const modal = document.getElementById('deleteModal');
  modal.classList.remove('show');
  gameToDelete = null;
}

// ========================================


// ========================================
// Event Listeners
// ========================================

// Status dropdown toggles
document.addEventListener('click', (e) => {
  const statusButton = e.target.closest('.status-select');
  
  if (statusButton) {
    e.stopPropagation();
    toggleStatusDropdown(statusButton);
  } else {
    // Close dropdown when clicking outside
    const existingDropdown = document.querySelector('.status-dropdown');
    if (existingDropdown) {
      const prevCard = existingDropdown.closest('.game-card');
      if (prevCard) prevCard.classList.remove('dropdown-open');
      existingDropdown.remove();
    }
  }
});

// Delete buttons - open modal
document.addEventListener('click', (e) => {
  const deleteButton = e.target.closest('.icon-btn');
  if (deleteButton) {
    e.stopPropagation();
    openDeleteModal(deleteButton);
  }
});

// Search input
if (searchInput) {
  searchInput.addEventListener('input', (e) => {
    handleSearch(e.target.value);
  });
}

// Sort buttons - Mutually exclusive selection
sortButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    // Remove active class from ALL buttons first
    sortButtons.forEach(b => b.classList.remove('active'));
    
    // Add active class ONLY to clicked button
    btn.classList.add('active');
    
    // Determine sort direction
    const isAsc = btn.querySelector('span').textContent.includes('0');
    currentSort = isAsc ? 'asc' : 'desc';
    
    // Apply sorting
    applyFiltersAndSort();
  });
});

// Status filter checkboxes - Handle click on the entire checkbox item (each independently)
document.querySelectorAll('.checkbox-item').forEach(item => {
  item.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    
    // Get only THIS item's checkbox and span
    const checkbox = item.querySelector('input[type="checkbox"]');
    const checkboxSpan = item.querySelector('.checkbox');
    
    // Toggle only THIS checkbox
    checkbox.checked = !checkbox.checked;
    
    // Update only THIS checkbox's visual state
    if (checkbox.checked) {
      checkboxSpan.classList.add('checked');
    } else {
      checkboxSpan.classList.remove('checked');
    }
    
    // Update the filter state (reads all but doesn't modify visuals)
    const label = checkbox.nextElementSibling;
    const statusName = label.textContent.toLowerCase().trim();
    
    let filterKey = 'planning';
    if (statusName.includes('progress')) filterKey = 'progress';
    else if (statusName === 'finished') filterKey = 'finished';
    else if (statusName === 'dropped') filterKey = 'dropped';
    
    activeFilters[filterKey] = checkbox.checked;
  });
});

// Apply button
if (applyButton) {
  applyButton.addEventListener('click', () => {
    applyFiltersAndSort();
    
    // Visual feedback
    applyButton.style.transform = 'scale(0.95)';
    setTimeout(() => {
      applyButton.style.transform = '';
    }, 150);
  });
}

// Delete Modal - Confirm button
document.getElementById('confirmDelete').addEventListener('click', confirmDeleteGame);

// Delete Modal - Cancel button
document.getElementById('cancelDelete').addEventListener('click', closeDeleteModal);

// Delete Modal - Close on overlay click
document.getElementById('deleteModal').addEventListener('click', (e) => {
  if (e.target === e.currentTarget) {
    closeDeleteModal();
  }
});

// Delete Modal - Close on Escape key
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    closeDeleteModal();
  }
});

