// ========================================
// PAGINATION SYSTEM
// ========================================

let currentPage = 1;
let gamesPerPage = 3;
let totalPages = 1;

function getResponsiveGamesPerPage() {
  const width = window.innerWidth;
  if (width <= 560) return 2;      // Mobile
  if (width <= 900) return 3;      // Tablet
  return 4;                        // Desktop
}

function initPagination() {
  gamesPerPage = getResponsiveGamesPerPage();
  calculateTotalPages();
  createPaginationControls();
  showPage(1);
}

function calculateTotalPages() {
  const allCards = collectionList.querySelectorAll('.game-card');
  const visibleCards = Array.from(allCards).filter(card => card.style.display !== 'none');
  totalPages = Math.ceil(visibleCards.length / gamesPerPage);
}

function createPaginationControls() {
  const existingPagination = document.querySelector('.pagination-controls');
  if (existingPagination) return;
  
  const paginationContainer = document.createElement('div');
  paginationContainer.className = 'pagination-controls';
  paginationContainer.innerHTML = `
    <button class="page-btn page-prev" id="prevPage">
      <svg width="8" height="12" viewBox="0 0 8 12" fill="none">
        <path d="M6 10L2 6L6 2" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
      </svg>
      Prev
    </button>
    <div class="page-numbers" id="pageNumbers"></div>
    <button class="page-btn page-next" id="nextPage">
      Next
      <svg width="8" height="12" viewBox="0 0 8 12" fill="none">
        <path d="M2 2L6 6L2 10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
      </svg>
    </button>
  `;
  
  const collectionPanel = document.querySelector('.collection-panel');
  collectionPanel.appendChild(paginationContainer);
  
  // Add event listeners
  document.getElementById('prevPage').addEventListener('click', () => {
    if (currentPage > 1) {
      showPage(currentPage - 1);
    }
  });
  
  document.getElementById('nextPage').addEventListener('click', () => {
    if (currentPage < totalPages) {
      showPage(currentPage + 1);
    }
  });
}

function showPage(pageNum) {
  currentPage = pageNum;
  
  const allCards = collectionList.querySelectorAll('.game-card');
  const visibleCards = Array.from(allCards).filter(card => card.style.display !== 'none');
  
  // Hide all visible cards first
  visibleCards.forEach(card => card.classList.add('page-hidden'));
  
  // Calculate range for current page
  const startIndex = (currentPage - 1) * gamesPerPage;
  const endIndex = startIndex + gamesPerPage;
  
  // Show cards for current page
  visibleCards.slice(startIndex, endIndex).forEach(card => {
    card.classList.remove('page-hidden');
  });
  
  // Update pagination controls
  updatePaginationControls();
  
  // Scroll to top of collection
  collectionList.scrollTop = 0;
  
}

function updatePaginationControls() {
  // Hide pagination entirely when there's only one page
  const paginationControls = document.querySelector('.pagination-controls');
  if (paginationControls) {
    paginationControls.style.display = totalPages > 1 ? 'flex' : 'none';
  }
  
  // Update prev/next button states
  const prevBtn = document.getElementById('prevPage');
  const nextBtn = document.getElementById('nextPage');
  
  if (prevBtn) {
    prevBtn.disabled = currentPage === 1;
    prevBtn.classList.toggle('disabled', currentPage === 1);
  }
  
  if (nextBtn) {
    nextBtn.disabled = currentPage === totalPages;
    nextBtn.classList.toggle('disabled', currentPage === totalPages);
  }
  
  // Update page numbers
  updatePageNumbers();
}

function updatePageNumbers() {
  const pageNumbersContainer = document.getElementById('pageNumbers');
  if (!pageNumbersContainer) return;
  
  pageNumbersContainer.innerHTML = '';
  
  for (let i = 1; i <= totalPages; i++) {
    const pageBtn = document.createElement('button');
    pageBtn.className = 'page-number-btn';
    pageBtn.textContent = i;
    
    if (i === currentPage) {
      pageBtn.classList.add('active');
    }
    
    pageBtn.addEventListener('click', () => showPage(i));
    pageNumbersContainer.appendChild(pageBtn);
  }
}

function refreshPagination() {
  calculateTotalPages();
  
  // If current page exceeds total pages, go to last page
  if (currentPage > totalPages) {
    currentPage = Math.max(1, totalPages);
  }
  
  showPage(currentPage);
}


// Override applyFiltersAndSort to refresh pagination
const originalApplyFiltersAndSort = applyFiltersAndSort;
applyFiltersAndSort = function() {
  originalApplyFiltersAndSort();
  refreshPagination();
};

// Initialize pagination after DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initPagination);
} else {
  initPagination();
}

// Recalculate games per page on resize (desktop <-> mobile)
let paginationResizeTimer;
window.addEventListener('resize', () => {
  clearTimeout(paginationResizeTimer);
  paginationResizeTimer = setTimeout(() => {
    const newGamesPerPage = getResponsiveGamesPerPage();
    if (newGamesPerPage !== gamesPerPage) {
      gamesPerPage = newGamesPerPage;
      refreshPagination();
    }
  }, 200);
});


// Fix: Dropdown options clean white text, card status colors
(function() {
  const dropdownFix = document.createElement('style');
  dropdownFix.textContent = `
    .status-option {
      color: #F4F4F4 !important;
    }
    .status-text.status-dropped {
      color: #FF6B35 !important;
    }
  `;
  document.head.appendChild(dropdownFix);
})();


// Stronger fix: More specific selector for dropdown
(function() {
  const strongFix = document.createElement('style');
  strongFix.textContent = `
    .status-dropdown .status-option.status-dropped,
    .status-option.status-dropped {
      color: #F4F4F4 !important;
    }
  `;
  document.head.appendChild(strongFix);
  
  // Force re-render after a brief delay to ensure override
  setTimeout(() => {
    document.querySelectorAll('.status-option').forEach(opt => {
      opt.style.color = '#F4F4F4';
    });
  }, 100);
})();
